// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC
   s sphere        -> SphereGeometry(1.15,64,48)  MeshPhysicalMaterial pink #dc9aa8, opacity .82, depthWrite off
   s nucleus       -> SphereGeometry(0.10,24,16)  MeshStandardMaterial #bcc74a opaque
   p lobe (x2)     -> LatheGeometry(cos-like profile, L=1.25, W=0.95) pink +Y, blue -Y, cusp at origin
   p nucleus       -> SphereGeometry(0.10) #49a04f
   p nodal plane   -> CircleGeometry(1.5) in XZ, gray translucent (shown on highlight)
   d lobe (x4)     -> LatheGeometry(L=1.15, W=0.85) rotated about Z to 135/45/-135/-45 deg
   d nuclei        -> SphereGeometry(0.10) #49a04f
   d nodal planes  -> two PlaneGeometry(2.8,2.8) crossing at origin (XZ and YZ), gray translucent
   captions        -> HTML labels via addLabel, bold, #1a1a1a, y = -1.72
   spacers         -> invisible tiny boxes to reserve caption room in camera auto-fit
*/

const PINK = 0xdc9aa8, BLUE = 0x7fa6d4, NUC_S = 0xbcc74a, NUC_G = 0x49a04f;

/* ── lighting ─────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xe8e8e8, 1.45));
const dirL = new THREE.DirectionalLight(0xffffff, 0.75);
dirL.position.set(-3.5, 4.0, 5.0);
scene.add(dirL);
const dirL2 = new THREE.DirectionalLight(0xffffff, 0.22);
dirL2.position.set(3, -2, -4);
scene.add(dirL2);

/* ── lobe geometry: revolved tapered "doorknob" profile ───────────────── */
function makeLobeGeometry(L, W) {
  const f = t => Math.pow(t, 0.9) * Math.pow(1 - t, 0.4);
  let mx = 0;
  for (let i = 0; i <= 400; i++) mx = Math.max(mx, f(i / 400));
  const pts = [];
  const N = 56;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    pts.push(new THREE.Vector2((W / 2) * f(t) / mx, L * t));
  }
  const g = new THREE.LatheGeometry(pts, 72);
  g.computeVertexNormals();
  return g;
}

function lobeMaterial(color) {
  return new THREE.MeshPhysicalMaterial({
    color: color,
    roughness: 0.82,
    metalness: 0.0,
    clearcoat: 0.0,
    sheen: 0.25,
    sheenColor: new THREE.Color(0xffffff),
    transparent: true,
    opacity: 0.82,
    depthWrite: false,
    side: THREE.DoubleSide,
    emissive: new THREE.Color(0x000000)
  });
}

function makeNucleus(color) {
  const m = new THREE.Mesh(
    new THREE.SphereGeometry(0.10, 28, 20),
    new THREE.MeshStandardMaterial({
      color: color, roughness: 0.45, metalness: 0.1,
      emissive: new THREE.Color(color).multiplyScalar(0.18),
      transparent: true, opacity: 1, depthWrite: true
    })
  );
  m.renderOrder = 20;
  return m;
}

