/* ── lobe geometry: revolved tapered "doorknob" profile ───────────────── */
function makeLobeGeometry(L, W) {
  const f = t => Math.pow(t, 0.9) * Math.pow(1 - t, 0.4);
  let mx = 0;
  for (let i = 0; i <= 400; i++) mx = Math.max(mx, f(i / 400));
  const pts = [];
  const N = 56;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    pts.push(new THREE.Vector2((W / 2) * f(t) / mx, L * t));
  }
  const g = new THREE.LatheGeometry(pts, 72);
  g.computeVertexNormals();
  return g;
}

function lobeMaterial(color) {
  return new THREE.MeshPhysicalMaterial({
    color: color,
    roughness: 0.82,
    metalness: 0.0,
    clearcoat: 0.0,
    sheen: 0.25,
    sheenColor: new THREE.Color(0xffffff),
    transparent: true,
    opacity: 0.82,
    depthWrite: false,
    side: THREE.DoubleSide,
    emissive: new THREE.Color(0x000000)
