   captions        -> HTML labels via addLabel, bold 15px, #1a1a1a, y = -1.98
   spacers         -> invisible tiny boxes reserving caption room for the camera auto-fit
   lighting        -> Hemisphere .55 + key Directional 1.05 upper-front-left + fill .3 + PointLight airbrush highlight
*/

const PINK = 0xdc9aa8, BLUE = 0x7fa6d4, NUC_S = 0xbcc74a, NUC_G = 0x49a04f;

/* ── lighting: soft matte, airbrush-like ──────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xece4e8, 0.55));
const keyL = new THREE.DirectionalLight(0xffffff, 1.05);
keyL.position.set(-4.0, 4.5, 6.0);
scene.add(keyL);
const fillL = new THREE.DirectionalLight(0xffffff, 0.30);
fillL.position.set(4.0, -1.5, 2.0);
scene.add(fillL);
const rimL = new THREE.DirectionalLight(0xffffff, 0.22);
rimL.position.set(1.0, -2.5, -5.0);
scene.add(rimL);
// soft hot-spot that gives the translucent surfaces a visible gradient
const spotL = new THREE.PointLight(0xffffff, 22, 18, 2);
spotL.position.set(-2.2, 2.4, 4.2);
scene.add(spotL);

/* ── lobe geometry: revolved cusp→fat→blunt profile ───────────────────── */
function makeLobeGeometry(L, W) {
  const f = t => Math.pow(t, 1.3) * Math.pow(1 - t, 0.5);
  let mx = 0;
  for (let i = 0; i <= 600; i++) mx = Math.max(mx, f(i / 600));
  const pts = [];
  const N = 72;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    pts.push(new THREE.Vector2((W / 2) * f(t) / mx, L * t));
  }
  const g = new THREE.LatheGeometry(pts, 80);
  g.computeVertexNormals();
  return g;
}

function lobeMaterial(color) {
  return new THREE.MeshPhysicalMaterial({
    color: color,
    roughness: 0.68,
    metalness: 0.0,
    clearcoat: 0.12,
    clearcoatRoughness: 0.9,
    sheen: 0.45,
    sheenRoughness: 0.9,
    sheenColor: new THREE.Color(0xffffff),
    transparent: true,
    opacity: 0.80,
    depthWrite: false,
    side: THREE.DoubleSide,
    emissive: new THREE.Color(0x000000)
  });
}

/* nucleus bead: drawn last, on top of every translucent surface */
function makeNucleus(color) {
  const grp = new THREE.Group();
  const bead = new THREE.Mesh(
    new THREE.SphereGeometry(0.115, 32, 24),
    new THREE.MeshStandardMaterial({
      color: color, roughness: 0.35, metalness: 0.05,
      emissive: new THREE.Color(color).multiplyScalar(0.45),
      transparent: true, opacity: 1,
      depthTest: false, depthWrite: false
    })
  );
  bead.renderOrder = 999;
  const glow = new THREE.Mesh(
    new THREE.SphereGeometry(0.175, 24, 18),
    new THREE.MeshBasicMaterial({
      color: new THREE.Color(color).lerp(new THREE.Color(0xffffff), 0.45),
      transparent: true, opacity: 0.30,
      depthTest: false, depthWrite: false,
      side: THREE.BackSide
    })
  );
  glow.renderOrder = 998;
  grp.add(glow); grp.add(bead);
  grp.userData.parts = [bead, glow];
  grp.userData.base = [1.0, 0.30];
  return grp;
}

function makeSpacers(group) {
  const gm = new THREE.BoxGeometry(0.01, 0.01, 0.01);
  const mm = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0 });
  [-2.25, 1.45].forEach(y => {
    const s = new THREE.Mesh(gm, mm);
    s.position.set(0, y, 0);
    s.visible = false;
    group.add(s);
  });
}

function nodalMaterial() {
  return new THREE.MeshBasicMaterial({
    color: 0x777777, transparent: true, opacity: 0,
    side: THREE.DoubleSide, depthWrite: false
  });
}

/* ── build the three orbitals ─────────────────────────────────────────── */
const ORB = {};
const ORDER = ['s', 'p', 'd'];

function addLobe(group, geo, color, sign, rotZ, title, body) {
  const mat = lobeMaterial(color);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.rotation.z = rotZ;
  mesh.userData.sign = sign;
  group.add(mesh);
  registerInteractive(mesh, {
    title: title,
    body: body,
    tooltip: (sign > 0 ? 'Pink lobe: ψ > 0' : 'Blue lobe: ψ < 0') + ' — click to highlight this sign',
    onClick: () => setHighlight(sign, true)
  });
  return { mesh, mat, sign, opa: 0.80 };
}

/* s orbital */
{
  const g = new THREE.Group();
  const mat = lobeMaterial(PINK);
  const sphere = new THREE.Mesh(new THREE.SphereGeometry(1.15, 72, 56), mat);
  sphere.userData.sign = 1;
  g.add(sphere);
  registerInteractive(sphere, {
    title: 'The s orbital — one sign, no nodes',
    body: 'The s orbital is spherical: the wave function has the same algebraic sign (pink, positive) in every direction, so there is no node and no second colour.',
    tooltip: 'Spherical s orbital: ψ > 0 everywhere',
    onClick: () => setHighlight(1, true)
  });
  const nuc = makeNucleus(NUC_S);
  g.add(nuc);
  registerInteractive(nuc.children[1], {
    title: 'The nucleus',
    body: 'The small yellow-green bead marks the nucleus at the exact centre of the spherical electron cloud.',
    tooltip: 'Nucleus'
  });
  makeSpacers(g);
  scene.add(g);
  ORB.s = { group: g, lobes: [{ mesh: sphere, mat, sign: 1, opa: 0.80 }], nuc, planes: [], appear: 1, target: 1, targetX: -3.4, allX: -3.4 };
}

/* p orbital */
{
  const g = new THREE.Group();
  const geo = makeLobeGeometry(1.25, 0.95);
  const lobes = [
    addLobe(g, geo, PINK, 1, 0,
      'p orbital: positive lobe',
      'The upper lobe carries positive amplitude (pink). It is a full, rotationally symmetric volume about the vertical axis — orbit the figure to see it.'),
    addLobe(g, geo, BLUE, -1, Math.PI,
      'p orbital: negative lobe',
      'The lower lobe is identical in shape but the wave function has the opposite sign (blue). Between the two lobes lies a nodal plane where ψ = 0.')
  ];
  const plane = new THREE.Mesh(new THREE.CircleGeometry(1.55, 64), nodalMaterial());
  plane.rotation.x = -Math.PI / 2;
  plane.renderOrder = 5;
  g.add(plane);
  const nuc = makeNucleus(NUC_G);
  g.add(nuc);
  registerInteractive(nuc.children[1], {
    title: 'The nucleus sits on the node',
    body: 'The green bead marks the nucleus exactly where the two lobes pinch to nothing — the point the nodal plane passes through.',
    tooltip: 'Nucleus at the pinch point'
  });
  makeSpacers(g);
  scene.add(g);
  ORB.p = { group: g, lobes, nuc, planes: [plane], appear: 1, target: 1, targetX: 0, allX: 0 };
}

/* d orbital */
{
  const g = new THREE.Group();
  const geo = makeLobeGeometry(1.15, 0.85);
  const defs = [[135, 1], [45, -1], [-135, -1], [-45, 1]];
  const lobes = defs.map(([ang, sign]) => addLobe(
    g, geo, sign > 0 ? PINK : BLUE, sign,
    THREE.MathUtils.degToRad(ang - 90),
    sign > 0 ? 'd orbital: positive lobe' : 'd orbital: negative lobe',
    'The four d lobes alternate in sign around the ring: crossing either nodal plane flips ψ from positive (pink) to negative (blue). Lobes of the same colour are diagonally opposite.'
  ));
  const p1 = new THREE.Mesh(new THREE.PlaneGeometry(2.9, 2.9), nodalMaterial());
  p1.rotation.x = -Math.PI / 2;            // XZ plane (y = 0)
  const p2 = new THREE.Mesh(new THREE.PlaneGeometry(2.9, 2.9), nodalMaterial());
  p2.rotation.y = Math.PI / 2;             // YZ plane (x = 0)
  p1.renderOrder = 5; p2.renderOrder = 5;
  g.add(p1); g.add(p2);
  const nuc = makeNucleus(NUC_G);
  g.add(nuc);
  registerInteractive(nuc.children[1], {
    title: 'The nucleus at the cloverleaf centre',
    body: 'All four lobes taper to the nucleus, where the two perpendicular nodal planes cross.',
    tooltip: 'Nucleus where both nodes cross'
  });
  makeSpacers(g);
  scene.add(g);
  ORB.d = { group: g, lobes, nuc, planes: [p1, p2], appear: 1, target: 1, targetX: 3.4, allX: 3.4 };
}

ORDER.forEach(k => { ORB[k].group.position.x = ORB[k].targetX; });

/* ── camera framing (measures only the currently-targeted shapes) ──────── */
function frameCamera() {
  const saved = ORDER.map(k => {
    const o = ORB[k];
    return { o, x: o.group.position.x, s: o.group.scale.x, v: o.group.visible };
  });
  const removed = [];
  ORDER.forEach(k => {
    const o = ORB[k];
    if (o.target > 0) {
      o.group.visible = true;
      o.group.position.x = o.targetX;
      o.group.scale.setScalar(1);
    } else {
      scene.remove(o.group);
      removed.push(o.group);
    }
  });
  setCameraView({
    projection: 'perspective',
    azimuthDeg: 15, elevationDeg: 12, rollDeg: 0,
    heightFraction: 0.62
  });
  removed.forEach(g => scene.add(g));
  saved.forEach(s => { s.o.group.position.x = s.x; s.o.group.scale.setScalar(s.s); s.o.group.visible = s.v; });
}

/* ── labels ───────────────────────────────────────────────────────────── */
const CAP_Y = -1.98;
const capS = addLabel('An <i>s</i> orbital', new THREE.Vector3(-3.4, CAP_Y, 0), { bold: true, fontSize: '15px', color: '#1a1a1a' });
const capP = addLabel('A <i>p</i> orbital', new THREE.Vector3(0, CAP_Y, 0), { bold: true, fontSize: '15px', color: '#1a1a1a' });
const capD = addLabel('A <i>d</i> orbital', new THREE.Vector3(3.4, CAP_Y, 0), { bold: true, fontSize: '15px', color: '#1a1a1a' });
ORB.s.cap = capS; ORB.p.cap = capP; ORB.d.cap = capD;

const nodeLblP = addLabel('nodal plane (&psi; = 0)', new THREE.Vector3(0, 0.16, 0), { fontSize: '11px', color: '#555' });
const nodeLblD = addLabel('two nodal planes', new THREE.Vector3(0, 0.16, 0), { fontSize: '11px', color: '#555' });
nodeLblP.div.style.opacity = 0;
nodeLblD.div.style.opacity = 0;

/* ── state & interaction ──────────────────────────────────────────────── */
const state = { mode: 'all', highlight: 0, bigNuc: false };

function setMode(mode) {
  state.mode = mode;
  ORDER.forEach(k => {
    const o = ORB[k];
    if (mode === 'all') { o.target = 1; o.targetX = o.allX; }
    else if (mode === k) { o.target = 1; o.targetX = 0; }
    else { o.target = 0; o.targetX = o.allX; }
  });
  if (state.highlight !== 0) setHighlight(0);
  document.querySelectorAll('.orbBtn').forEach(b =>
    b.classList.toggle('active', b.dataset.orb === mode));
  frameCamera();
}

function setHighlight(sign, toggle) {
  if (toggle && state.highlight === sign) sign = 0;
  state.highlight = sign;
  document.getElementById('hlPos').classList.toggle('active', sign === 1);
  document.getElementById('hlNeg').classList.toggle('active', sign === -1);
}

document.querySelectorAll('.orbBtn').forEach(b => {
  b.addEventListener('click', () => setMode(b.dataset.orb));
});
document.getElementById('hlPos').addEventListener('click', () => setHighlight(1, true));
document.getElementById('hlNeg').addEventListener('click', () => setHighlight(-1, true));
document.getElementById('hlClear').addEventListener('click', () => setHighlight(0));
document.getElementById('nucBig').addEventListener('change', (e) => {
  state.bigNuc = e.target.checked;
});

/* ── guided tour ──────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The s orbital', text: 'A single pink sphere surrounds the yellow-green nucleus. The wave function has one sign everywhere and no nodes, so there is only one colour.', mode: 's' },
  { title: 'The p orbital and its node', text: 'Two doorknob lobes meet at the nucleus. The pink lobe above and blue lobe below carry opposite signs; the pinch between them is a nodal plane where ψ = 0.', mode: 'p' },
  { title: 'The d orbital: signs alternate', text: 'Four lobes form a cloverleaf — pink at upper-left and lower-right, blue at upper-right and lower-left. Click any lobe to highlight its partner and see the sign flip on every crossing of a node.', mode: 'd' },
  { title: 'Compare all three', text: 'Side by side the progression is clear: 0 nodes and 1 lobe, 1 node and 2 lobes, 2 nodes and 4 lobes.', mode: 'all' }
];
let stepIdx = 3;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + s.title;
  document.getElementById('stepText').textContent = s.text;
  setMode(s.mode);
}
document.getElementById('prevStep').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── per-frame tweening ───────────────────────────────────────────────── */
const _tmpCol = new THREE.Color();
let _last = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;
  const k = 1 - Math.pow(0.0015, dt);
  const nucScale = state.bigNuc ? 2.1 : 1.0;

  ORDER.forEach(key => {
    const o = ORB[key];
    o.appear += (o.target - o.appear) * k;
    o.group.position.x += (o.targetX - o.group.position.x) * k;
    const a = o.appear;
    o.group.visible = a > 0.01;
    o.group.scale.setScalar(0.86 + 0.14 * a);

    o.lobes.forEach(L => {
      let base;
      if (state.highlight === 0) base = 0.80;
      else base = (L.sign === state.highlight) ? 0.93 : 0.24;
      L.opa += (base - L.opa) * k;
      L.mat.opacity = L.opa * a;
      const on = (state.highlight !== 0 && L.sign === state.highlight);
      _tmpCol.set(L.mat.color).multiplyScalar(on ? 0.28 : 0.0);
      L.mat.emissive.lerp(_tmpCol, k);
    });

    const parts = o.nuc.userData.parts, bases = o.nuc.userData.base;
    parts.forEach((p, i) => { p.material.opacity = bases[i] * a; });
    o.nuc.scale.setScalar(o.nuc.scale.x + (nucScale - o.nuc.scale.x) * k);

    const planeTarget = (state.highlight !== 0 && o.target > 0) ? 0.17 : 0.0;
    o.planes.forEach(p => {
      p.material.opacity += (planeTarget * a - p.material.opacity) * k;
      p.visible = p.material.opacity > 0.004;
    });

    if (o.cap) {
      o.cap.pos.set(o.group.position.x, CAP_Y, 0);
      o.cap.div.style.opacity = a;
    }
  });

  nodeLblP.pos.set(ORB.p.group.position.x + 1.40, 0.20, 0);
  nodeLblD.pos.set(ORB.d.group.position.x + 1.55, 0.20, 0);
  nodeLblP.div.style.opacity = (state.highlight !== 0 ? 1 : 0) * ORB.p.appear;
  nodeLblD.div.style.opacity = (state.highlight !== 0 ? 1 : 0) * ORB.d.appear;
}
tick();

/* ── initial view: all three, exactly like the printed figure ─────────── */
goToStep(3);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
